class GainReductionComputer
{
public:
    void setThreshold(float thresholdDB) { threshold = thresholdDB; }
    void setRatio(float r) { ratio = r; }
    void setAttack(float attackMs) { attackTime = attackMs / 1000.0f; }
    void setRelease(float releaseMs) { releaseTime = releaseMs / 1000.0f; }

    void prepare(double sampleRate, int maxBlockSize)
    {
        this->sampleRate = sampleRate;
        attackCoeff = std::exp(-1.0 / (attackTime * sampleRate));
        releaseCoeff = std::exp(-1.0 / (releaseTime * sampleRate));
    }

    float computeGainReduction(float inputLevel)
    {
        // Convert to dB
        float inputDB = 20.0f * std::log10(inputLevel + 1e-10f);

        // Compute gain reduction
        float gainReduction = 0.0f;
        if (inputDB > threshold)
        {
            gainReduction = (inputDB - threshold) * (1.0f - 1.0f / ratio);
        }

        // Convert back to linear
        return std::pow(10.0f, -gainReduction / 20.0f);
    }

    float process(float inputLevel)
    {
        float targetGain = computeGainReduction(inputLevel);

        // Smooth gain reduction
        if (targetGain < currentGain)
        {
            // Attack
            currentGain = attackCoeff * currentGain + (1.0f - attackCoeff) * targetGain;
        }
        else
        {
            // Release
            currentGain = releaseCoeff * currentGain + (1.0f - releaseCoeff) * targetGain;
        }

        return currentGain;
    }

private:
    float threshold = 0.0f;
    float ratio = 10.0f;
    float attackTime = 0.001f;
    float releaseTime = 0.1f;
    double sampleRate = 44100.0;
    float attackCoeff = 0.0f;
    float releaseCoeff = 0.0f;
    float currentGain = 1.0f;
};

class LookAheadGainReduction
{
public:
    void prepare(double sampleRate, int maxBlockSize, float lookaheadMs)
    {
        this->sampleRate = sampleRate;
        lookaheadSamples = static_cast<int>(lookaheadMs / 1000.0f * sampleRate);

        delayBuffer.resize(lookaheadSamples * 2);  // For delay line
        gainReductionBuffer.resize(lookaheadSamples * 2);

        std::fill(delayBuffer.begin(), delayBuffer.end(), 0.0f);
        std::fill(gainReductionBuffer.begin(), gainReductionBuffer.end(), 1.0f);
    }

    void pushSample(float input)
    {
        delayBuffer[writeIndex] = input;
        writeIndex = (writeIndex + 1) % delayBuffer.size();
    }

    void pushGainReduction(float gainReduction)
    {
        gainReductionBuffer[writeIndex] = gainReduction;
    }

    float popSample()
    {
        float output = delayBuffer[readIndex];
        readIndex = (readIndex + 1) % delayBuffer.size();
        return output;
    }

    float getDelayedGainReduction()
    {
        return gainReductionBuffer[readIndex];
    }

    int getLatency() const { return lookaheadSamples; }

private:
    double sampleRate = 44100.0;
    int lookaheadSamples = 0;
    std::vector<float> delayBuffer;
    std::vector<float> gainReductionBuffer;
    int writeIndex = 0;
    int readIndex = 0;
};

class GainReductionSmoother
{
public:
    void prepare(double sampleRate, float lookaheadMs)
    {
        // Compute coefficients for reverse filtering
        // The smoothing time should be less than lookahead time
        int smoothingSamples = static_cast<int>(lookaheadMs / 1000.0f * sampleRate);

        // Create smoothing coefficients (reverse filtering)
        smoothingCoefficients.resize(smoothingSamples);
        for (int i = 0; i < smoothingSamples; ++i)
        {
            // Linear fade in for gain reduction
            smoothingCoefficients[i] = static_cast<float>(i) / smoothingSamples;
        }
    }

    float process(float currentGain, const float* history, int historyLength)
    {
        // Smooth by blending current gain with historical values
        float smoothedGain = currentGain;

        for (int i = 0; i < historyLength && i < smoothingCoefficients.size(); ++i)
        {
            // Reverse order: older values have less weight
            smoothedGain = std::min(smoothedGain, history[i]);
        }

        return smoothedGain;
    }

private:
    std::vector<float> smoothingCoefficients;
};

class LookAheadLimiter
{
public:
    void prepare(double sampleRate, int maxBlockSize)
    {
        gainReductionComputer.prepare(sampleRate, maxBlockSize);
        lookahead.prepare(sampleRate, maxBlockSize, lookaheadMs);
        smoother.prepare(sampleRate, lookaheadMs);
    }

    void processBlock(AudioBuffer<float>& buffer)
    {
        auto* channelData = buffer.getWritePointer(0);
        int numSamples = buffer.getNumSamples();

        // Process in reverse to "look ahead"
        for (int i = numSamples - 1; i >= 0; --i)
        {
            // Compute gain reduction
            float level = std::abs(channelData[i]);
            float gainReduction = gainReductionComputer.process(level);

            // Push to lookahead buffer
            lookahead.pushSample(channelData[i]);
            lookahead.pushGainReduction(gainReduction);
        }

        // Process forward with delayed samples
        for (int i = 0; i < numSamples; ++i)
        {
            float delayedSample = lookahead.popSample();
            float delayedGain = lookahead.getDelayedGainReduction();

            // Apply smoothed gain reduction
            channelData[i] = delayedSample * delayedGain;
        }
    }

    int getLatency() const { return lookahead.getLatency(); }

private:
    GainReductionComputer gainReductionComputer;
    LookAheadGainReduction lookahead;
    GainReductionSmoother smoother;
    float lookaheadMs = 5.0f;
};

// Limiter settings
void setLimiter()
{
    threshold = -0.3f;  // dB
    ratio = 100.0f;    // Infinite for limiting
    attack = 0.001f;   // 1ms
    release = 0.05f;   // 50ms
    lookahead = 5.0f;  // ms
}

// Compressor settings
void setCompressor()
{
    threshold = -20.0f;  // dB
    ratio = 4.0f;
    attack = 0.01f;     // 10ms
    release = 0.1f;     // 100ms
    lookahead = 0.0f;   // No lookahead needed
}

class LimiterProcessor
{
public:
    void prepare(double sampleRate, int maxBlockSize)
    {
        limiter.prepare(sampleRate, maxBlockSize);

        // Report latency to host for PDC
        // setLatencySamples(limiter.getLatency());
    }

    void processBlock(AudioBuffer<float>& buffer)
    {
        limiter.processBlock(buffer);
    }

    void setThreshold(float db) { limiter.setThreshold(db); }
    void setRelease(float ms) { limiter.setRelease(ms); }

private:
    LookAheadLimiter limiter;
};

